== RD compose 1466-1546
    // inputs, each delayed to its scene's offset in the trimmed timeline,
    // then mixed into one audio track (the raw capture has no audio).
    const SUBTITLE_STYLE =
      "FontSize=14,PrimaryColour=&HFFFFFF&,BackColour=&HA0000000&,BorderStyle=4,Outline=0,Shadow=0,MarginV=24";
    const outScale = dpr > 1 ? 1.5 : 1;
    const outWidth = Math.round((viewport.width * outScale) / 2) * 2;
    const outHeight = Math.round((viewport.height * outScale) / 2) * 2;
    const filterParts: string[] = [
      `[0:v]scale=${outWidth}:${outHeight}:flags=lanczos[vscaled]`,
    ];
    let videoLabel = "[vscaled]";
    if (srtPath) {
      filterParts.push(
        `${videoLabel}subtitles=filename='${srtPath}':force_style='${SUBTITLE_STYLE}'[vout]`,
      );
      videoLabel = "[vout]";
    }
    if (toastAssPath) {
      filterParts.push(
        `${videoLabel}subtitles=filename='${toastAssPath}'[vtoasts]`,
      );
      videoLabel = "[vtoasts]";
    }
    const narration = [...narrationClips.values()]
      .map((clip) => ({
        ...clip,
        offsetMs: Math.max(
          0,
          Math.round(sceneMarks[clip.sceneIndex].atMs - trimOffsetMs),
        ),
      }))
      .sort((a, b) => a.sceneIndex - b.sceneIndex);
    if (narration.length) {
      const delayed = narration.map((clip, i) => {
        filterParts.push(`[${i + 1}:a]adelay=${clip.offsetMs}:all=1[a${i}]`);
        return `[a${i}]`;
      });
      // Clean the synthetic speech: highpass rumble, non-local-means
      // denoise (kills Kokoro's hiss under and around words), gate the
      // pauses to true silence, then LINEAR loudnorm — dynamic loudnorm
      // pumps the floor up around speech, which is audible as "hush".
      filterParts.push(
        `${delayed.join("")}amix=inputs=${narration.length}:normalize=0,` +
          `highpass=f=80,anlmdn=s=7:p=0.002:r=0.006,` +
          `agate=threshold=0.01:ratio=8:attack=5:release=140,` +
          `loudnorm=I=-16:TP=-1.5:LRA=11:linear=true[aout]`,
      );
    }

    await runFfmpeg([
      "-y",
      "-ss",
      trimSeconds.toFixed(2),
      "-i",
      rawVideoPath,
      ...narration.flatMap((clip) => ["-i", clip.path]),
      ...(filterParts.length
        ? ["-filter_complex", filterParts.join(";"), "-map", videoLabel]
        : []),
      ...(narration.length
        ? ["-map", "[aout]", "-c:a", "aac", "-b:a", "192k", "-ar", "48000"]
        : []),
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-crf",
      "23",
      "-pix_fmt",
      "yuv420p",
      "-movflags",
      "+faststart",
      mp4Target,
    ]);

    if (getBooleanArg(args, "keep-webm")) {
      await fs.rename(rawVideoPath, webmTarget);
      log(`Raw video: ${webmTarget}`);
    }
    await fs.rm(recordingDir, { recursive: true, force: true });
    log(`Demo video: ${mp4Target}`);
