import assert from "node:assert/strict";
import test from "node:test";
import type { Action } from "../../recorder/recordDemo";
import { Journal, type JournalEvent } from "../journal";
import {
  Machine,
  scaleAction,
  type Executor,
  type MachineOptions,
  type MachineState,
} from "../machine";
import { validatePlan } from "../plan";

class FakeExecutor implements Executor {
  actions: Action[] = [];
  checks: string[] = [];
  failures = 0;
  states: MachineState[] = [];

  async run(action: Action): Promise<void> {
    this.actions.push(action);
    if (this.failures > 0) {
      this.failures -= 1;
      throw new Error("locator.click: Timeout 45000ms exceeded.");
    }
  }

  async check(js: string): Promise<void> {
    this.checks.push(js);
    if (js.includes("FAIL")) throw new Error("Expected 2 rows, saw 1");
  }

  async snapshot(): Promise<string> {
    return "- main: fake page";
  }

  async render(state: MachineState): Promise<void> {
    this.states.push(state);
  }
}

const setup = (
  rawPlan: unknown,
  options: Partial<Omit<MachineOptions, "plan" | "journal" | "executor">> = {},
) => {
  const journal = new Journal(null);
  const executor = new FakeExecutor();
  const machine = new Machine({
    plan: validatePlan(rawPlan),
    journal,
    executor,
    dwellMs: 0,
    ...options,
  });
  return { journal, executor, machine };
};

const waitForEvent = async (
  journal: Journal,
  type: string,
  nth = 1,
  timeoutMs = 2000,
): Promise<JournalEvent> => {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    const matches = journal.all().filter((event) => event.type === type);
    if (matches.length >= nth) return matches[nth - 1];
    const left = deadline - Date.now();
    if (left <= 0) {
      throw new Error(
        `No "${type}" event within ${timeoutMs} ms. Saw: ${journal
          .all()
          .map((event) => event.type)
          .join(", ")}`,
      );
    }
    await journal.wait(journal.lastSeq, left);
  }
};

const delay = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

test("plan steps run in order and js expectations decide the verdict", async () => {
  const { executor, machine } = setup({
    name: "t",
    cases: [
      {
        id: "a",
        title: "A",
        steps: [
          { do: { click: "#one" }, why: "open" },
          { do: { press: "Enter" }, why: "confirm" },
        ],
        expect: { js: "1" },
      },
      {
        id: "b",
        title: "B",
        steps: [{ do: { click: "#two" }, why: "open" }],
        expect: { js: "FAIL" },
      },
    ],
  });
  await machine.run();
  assert.deepEqual(executor.actions, [
    { click: "#one" },
    { press: "Enter" },
    { click: "#two" },
  ]);
  assert.deepEqual(machine.results, { a: "pass", b: "fail" });
  assert.match(machine.notes.b, /Expected 2 rows/);
});

test("a case with only an intent waits for the brain's steps", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "open the settings" }],
  });
  const running = machine.run();
  const need = await waitForEvent(journal, "need-steps");
  assert.equal(need.aria, "- main: fake page");
  assert.equal(machine.state().phase, "waiting-steps");
  const result = machine.command("socket", "steps", {
    steps: [{ do: { click: "text=Settings" }, why: "open the settings" }],
  });
  assert.equal(result.ok, true);
  await running;
  assert.deepEqual(executor.actions, [{ click: "text=Settings" }]);
  assert.equal(machine.plan.cases[0].steps[0].source, "model");
  assert.deepEqual(machine.results, { a: "pass" });
});

test("js from the socket waits for the HUD, and the socket can't approve it", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "seed a page" }],
  });
  const running = machine.run();
  await waitForEvent(journal, "need-steps");
  machine.command("socket", "steps", {
    steps: [{ do: { js: "window.seeded = true" }, why: "seed the page" }],
  });
  const need = await waitForEvent(journal, "need-approval");
  const stepId = String(need.stepId);
  const fromSocket = machine.command("socket", "approve", { stepId });
  assert.equal(fromSocket.ok, false);
  assert.equal(executor.actions.length, 0);
  assert.equal(machine.command("hud", "approve", { stepId: "nope" }).ok, false);
  assert.equal(machine.command("hud", "approve", { stepId }).ok, true);
  await running;
  assert.deepEqual(executor.actions, [{ js: "window.seeded = true" }]);
  assert.equal(machine.plan.cases[0].steps[0].approved, true);
});

test("a denied step never runs and leaves the working plan", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", intent: "clean up" }],
  });
  const running = machine.run();
  await waitForEvent(journal, "need-steps");
  machine.command("socket", "steps", {
    steps: [
      { do: { js: "deleteEverything()" }, why: "clean up" },
      { do: { click: "#ok" }, why: "confirm" },
    ],
  });
  const need = await waitForEvent(journal, "need-approval");
  machine.command("hud", "deny", { stepId: String(need.stepId) });
  await running;
  assert.deepEqual(executor.actions, [{ click: "#ok" }]);
  assert.deepEqual(
    machine.plan.cases[0].steps.map((step) => step.why),
    ["confirm"],
  );
});

test("a failed step waits until it's retried", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", steps: [{ do: { click: "#flaky" }, why: "open" }] }],
  });
  executor.failures = 1;
  const running = machine.run();
  const failed = await waitForEvent(journal, "step-failed");
  assert.match(String(failed.error), /Timeout/);
  assert.equal(failed.aria, "- main: fake page");
  assert.equal(machine.state().phase, "step-failed");
  machine.command("socket", "retry");
  await running;
  assert.equal(executor.actions.length, 2);
  assert.deepEqual(machine.results, { a: "pass" });
});

test("replace-failed swaps the failed step for the brain's fix", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [{ id: "a", title: "A", steps: [{ do: { click: "#flaky" }, why: "open" }] }],
  });
  executor.failures = 1;
  const running = machine.run();
  await waitForEvent(journal, "step-failed");
  const fix = machine.command("socket", "steps", {
    how: "replace-failed",
    steps: [{ do: { click: 'role=button[name="Open"]' }, why: "open it from the toolbar" }],
  });
  assert.equal(fix.ok, true);
  await running;
  assert.deepEqual(executor.actions, [
    { click: "#flaky" },
    { click: 'role=button[name="Open"]' },
  ]);
  assert.deepEqual(
    machine.plan.cases[0].steps.map((step) => step.why),
    ["open it from the toolbar"],
  );
});

test("pause holds the next step until resume", async () => {
  const { journal, executor, machine } = setup({
    name: "t",
    cases: [
      {
        id: "a",
        title: "A",
        steps: [
          { do: { click: "#1" }, why: "one" },
          { do: { click: "#2" }, why: "two" },
        ],
      },
    ],
  });
  machine.command("hud", "pause");
  const running = machine.run();
  await waitForEvent(journal, "case-start");
  await delay(40);
  assert.equal(executor.actions.length, 0);
  assert.equal(machine.state().phase, "paused");
  machine.command("hud", "resume");
  await running;
  assert.equal(executor.actions.length, 2);
});

test("step mode runs one step per next", async () => {
  const { journal, executor, machine } = setup(
    {
      name: "t",
      cases: [
        {
          id: "a",
          title: "A",
          steps: [
            { do: { click: "#1" }, why: "one" },
            { do: { click: "#2" }, why: "two" },
          ],
        },
      ],
    },
    { mode: "step" },
  );
  const running = machine.run();
  await waitForEvent(journal, "case-start");
  await delay(30);
  assert.equal(executor.actions.length, 0);
  assert.equal(machine.state().phase, "waiting-next");
  machine.command("hud", "next");
  await waitForEvent(journal, "step-done");
  await delay(30);
  assert.equal(executor.actions.length, 1);
  machine.command("hud", "next");
  await running;
  assert.equal(executor.actions.length, 2);
});

test("text expectations wait for your verdict; the brain only proposes one", async () => {
  const { journal, machine } = setup({
    name: "t",
    cases: [
      {
        id: "a",
        title: "A",
        steps: [{ do: { click: "#x" }, why: "open" }],
        expect: { text: "The warning names Stored Relations" },
      },
    ],
  });
  const running = machine.run();
  await waitForEvent(journal, "need-verdict");
  const proposal = machine.command("socket", "verdict", {
    verdict: "pass",
    reason: "the banner is visible",
  });
  assert.equal(proposal.ok, true);
  const pending = machine.state().pending;
  assert.equal(pending?.kind, "verdict");
  assert.equal(pending?.kind === "verdict" ? pending.proposal?.verdict : null, "pass");
  assert.deepEqual(machine.results, {});
  machine.command("hud", "verdict", { verdict: "fail", note: "wrong wording" });
  await running;
  assert.deepEqual(machine.results, { a: "fail" });
  assert.equal(machine.notes.a, "wrong wording");
});

test("failing a case from the HUD ends it with your note", async () => {
  const { journal, executor, machine } = setup(
    {
      name: "t",
      cases: [
        {
          id: "a",
          title: "A",
          steps: [
            { do: { click: "#1" }, why: "one" },
            { do: { click: "#2" }, why: "two" },
          ],
        },
      ],
    },
    { mode: "step" },
  );
  const running = machine.run();
  await waitForEvent(journal, "case-start");
  machine.command("hud", "verdict", { verdict: "fail", note: "button overlaps the label" });
  await running;
  assert.equal(executor.actions.length, 0);
  assert.deepEqual(machine.results, { a: "fail" });
  assert.equal(machine.notes.a, "button overlaps the label");
});

test("steps from the socket must stay on the graph's origin", () => {
  const { machine } = setup(
    { name: "t", cases: [{ id: "a", title: "A", intent: "open a page" }] },
    { origin: "https://roamresearch.com" },
  );
  const away = machine.command("socket", "steps", {
    caseId: "a",
    steps: [{ do: { open: "https://evil.example/x" }, why: "leave" }],
  });
  assert.equal(away.ok, false);
  const home = machine.command("socket", "steps", {
    caseId: "a",
    steps: [{ do: { open: "#/app/test-3-graph/page/abc" }, why: "open the page" }],
  });
  assert.equal(home.ok, true);
});

test("a case added after the plan finishes runs, and stop ends the session", async () => {
  const { journal, executor, machine } = setup(
    {
      name: "t",
      cases: [{ id: "a", title: "A", steps: [{ do: { click: "#a" }, why: "a" }] }],
    },
    { stayOpen: true },
  );
  const running = machine.run();
  await waitForEvent(journal, "plan-done");
  const added = machine.command("socket", "add-case", {
    by: "you",
    case: { title: "B", steps: [{ do: { click: "#b" }, why: "b" }] },
  });
  assert.equal(added.ok, true);
  await waitForEvent(journal, "plan-done", 2);
  machine.command("hud", "stop");
  await running;
  assert.deepEqual(executor.actions, [{ click: "#a" }, { click: "#b" }]);
  assert.equal(machine.plan.cases[1].steps[0].source, "you");
  assert.deepEqual(machine.results, { a: "pass", c2: "pass" });
});

test("speed scales pauses and typing, and leaves other actions alone", () => {
  assert.deepEqual(scaleAction({ pause: 2 }, 2), { pause: 1 });
  assert.deepEqual(scaleAction({ type: { into: "#q", text: "hi" } }, 2), {
    type: { into: "#q", text: "hi", delay_ms: 25 },
  });
  assert.deepEqual(scaleAction({ command_palette: "Open settings" }, 0.5), {
    command_palette: { label: "Open settings", type_delay_ms: 120 },
  });
  assert.deepEqual(scaleAction({ click: "#x" }, 3), { click: "#x" });
});

