import path from "node:path";
import type { BrowserContext, Page } from "playwright";
import {
  CURSOR_INIT_SCRIPT,
  buildPickerShimScript,
  loadDeveloperExtension,
  readFolderFiles,
} from "../recorder/recordDemo";
import {
  defaultChromium,
  graphNameFromRoamUrl,
  resolveSlotConfig,
  waitForRoamReady,
  type SlotConfig,
} from "../../discourse-graph/apps/roam/scripts/playwright/roamSession";

export const DEV_GRAPH = "discourse-dev-graph";

export type ProofTarget = { slotConfig: SlotConfig; graph: string };

// Kits write to the graph, so they run on test-3-graph unless told otherwise,
// and never on discourse-dev-graph without an explicit override.
export const resolveTarget = ({
  slot,
  url,
  allowDevGraph,
}: {
  slot?: string;
  url?: string;
  allowDevGraph: boolean;
}): ProofTarget => {
  const slotConfig = resolveSlotConfig({
    slot: slot || "3",
    requireCredentials: false,
    graphUrl: url,
  });
  const graph = graphNameFromRoamUrl(slotConfig.graphUrl);
  if (graph === DEV_GRAPH && !allowDevGraph) {
    throw new Error(
      "This kit would run on discourse-dev-graph. Kits write to the graph, so they default to test-3-graph (slot 3). Pass --allow-dev-graph to override.",
    );
  }
  return { slotConfig, graph };
};

const PROFILE_IN_USE =
  /processsingleton|profile.*(?:lock|in use)|singletonlock|already running|existing browser session/i;

export type ProofSession = {
  context: BrowserContext;
  page: Page;
  // Closes the browser and returns the session footage, if it was recorded.
  close(): Promise<string | null>;
};

export const openProofSession = async ({
  target,
  viewport,
  dpr,
  distDir,
  cursor,
  recordDir,
  initScripts = [],
  beforeNavigate,
  allowLogin,
  timeout,
}: {
  target: ProofTarget;
  viewport: { width: number; height: number };
  dpr: number;
  distDir: string | null;
  cursor: boolean;
  recordDir?: string;
  initScripts?: string[];
  beforeNavigate?: (context: BrowserContext) => Promise<void>;
  allowLogin: boolean;
  timeout: number;
}): Promise<ProofSession> => {
  const distFiles = distDir ? await readFolderFiles(distDir) : null;
  let context: BrowserContext;
  try {
    context = await defaultChromium.launchPersistentContext(
      target.slotConfig.profileDir,
      {
        headless: false,
        viewport,
        deviceScaleFactor: dpr,
        recordVideo: recordDir
          ? {
              dir: recordDir,
              size: {
                width: viewport.width * dpr,
                height: viewport.height * dpr,
              },
            }
          : undefined,
        args: [
          "--disable-features=LocalNetworkAccessChecks",
          `--force-device-scale-factor=${dpr}`,
          "--hide-crash-restore-bubble",
        ],
      },
    );
  } catch (error) {
    if (PROFILE_IN_USE.test(String(error))) {
      throw new Error(
        `Profile slot ${target.slotConfig.slot} is in use by another session. Wait for it to finish, or pick another slot with --slot.`,
      );
    }
    throw error;
  }

  try {
    if (beforeNavigate) await beforeNavigate(context);
    if (distDir && distFiles) {
      await context.addInitScript(
        buildPickerShimScript(path.basename(distDir), distFiles),
      );
    }
    if (cursor) await context.addInitScript(CURSOR_INIT_SCRIPT);
    for (const script of initScripts) await context.addInitScript(script);

    const page = context.pages()[0] ?? (await context.newPage());
    for (const extra of context.pages()) {
      if (extra !== page) await extra.close().catch(() => undefined);
    }
    await page.goto(target.slotConfig.graphUrl, {
      waitUntil: "domcontentloaded",
    });
    await page
      .waitForSelector(
        '.roam-app, .roam-body, input[placeholder="Find or Create Page"], input[type="password"]',
        { timeout },
      )
      .catch(() => undefined);
    await waitForRoamReady({
      page,
      slotConfig: target.slotConfig,
      headless: false,
      allowInteractiveLogin: allowLogin,
      timeout,
    });
    if (distDir) await loadDeveloperExtension({ page, distDir, timeout });

    return {
      context,
      page,
      close: async () => {
        const video = page.video();
        await page.close().catch(() => undefined);
        await context.close().catch(() => undefined);
        return video ? video.path().catch(() => null) : null;
      },
    };
  } catch (error) {
    await context.close().catch(() => undefined);
    throw error;
  }
};

