import fs from "node:fs/promises";
import path from "node:path";
import type { Baseline, Kit, Need } from "./kit";
import { envRefs } from "./template";

export const SUPABASE_URL = "http://127.0.0.1:54321";
export const EMBED_STUB_URL = "http://127.0.0.1:3210";
export const DG_REPO = "DiscourseGraphs/discourse-graph";

const DISCOURSE_GRAPH_ROOT = path.resolve(__dirname, "../../discourse-graph");
const DATABASE_DIR = path.join(DISCOURSE_GRAPH_ROOT, "packages/database");
const EMBED_STUB = path.resolve(__dirname, "../recorder/embed-stub.py");

export type NeedResult = {
  id: string;
  ok: boolean;
  detail: string;
  fix?: string;
};

export type Probes = {
  // The HTTP status, or null when nothing answers.
  http(url: string, init?: RequestInit): Promise<number | null>;
  shell(command: string): Promise<{ code: number; output: string }>;
  readFile(file: string): Promise<string | null>;
  prHead(pr: number): Promise<string | null>;
};

const runShell = (command: string): Promise<{ code: number; output: string }> =>
  new Promise((resolve) => {
    const child = spawn("/bin/sh", ["-c", command], {
      stdio: ["ignore", "pipe", "pipe"],
      env: process.env,
    });
    let output = "";
    child.stdout.on("data", (chunk: Buffer) => {
      output += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      output += chunk.toString();
    });
    const timer = setTimeout(() => child.kill("SIGTERM"), 120_000);
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code: code ?? 1, output: output.slice(-4000) });
    });
  });

export const defaultProbes: Probes = {
  http: async (url, init) => {
    try {
      const response = await fetch(url, {
        ...init,
        signal: AbortSignal.timeout(4000),
      });
      return response.status;
    } catch {
      return null;
    }
  },
  shell: runShell,
  readFile: (file) => fs.readFile(file, "utf8").catch(() => null),
  prHead: async (pr) => {
    const result = await runShell(
      `gh pr view ${pr} --repo ${DG_REPO} --json headRefOid --jq .headRefOid`,
    );
    return result.code === 0 ? result.output.trim() : null;
  },
};

const EXPORT_DB_ENV = `set -a; . ${path.join(DATABASE_DIR, ".env.local")}; set +a`;

// Everything a run needs, from the kit's own list plus what its fixtures and
// strings imply: a rest or sql fixture needs Supabase, {{env.X}} needs X.
export const collectNeeds = (
  kit: Kit,
  baseline: Baseline | null,
): Need[] => {
  const needs = new Map<string, Need>();
  const add = (need: Need): void => {
    needs.set(typeof need === "string" ? need : need.id, need);
  };
  for (const need of kit.needs ?? []) add(need);
  const fixtures = [...(baseline?.prepare ?? []), ...(kit.prepare ?? [])];
  for (const fixture of fixtures) {
    const kinds = [
      ...Object.keys(fixture.apply),
      ...(fixture.check ? Object.keys(fixture.check) : []),
    ];
    if (kinds.includes("rest") || kinds.includes("sql")) add("supabase");
    if (kinds.includes("rest")) add("env:SUPABASE_SERVICE_ROLE_KEY");
  }
  for (const name of envRefs([kit, baseline])) add(`env:${name}`);
  return [...needs.values()];
};

export const buildCommitOf = (extensionJs: string): string | null =>
  /buildCommit:"([0-9a-f]{7,40})"/.exec(extensionJs)?.[1] ?? null;

export const checkNeeds = async ({
  kit,
  baseline,
  distDir,
  env = process.env,
  probes = defaultProbes,
  allowStaleBuild = false,
}: {
  kit: Kit;
  baseline: Baseline | null;
  distDir: string | null;
  env?: NodeJS.ProcessEnv;
  probes?: Probes;
  allowStaleBuild?: boolean;
}): Promise<NeedResult[]> => {
  const needs = collectNeeds(kit, baseline);
  const ids = new Set(needs.map((need) => (typeof need === "string" ? need : need.id)));
  const results: NeedResult[] = [];

  for (const need of needs) {
    if (typeof need !== "string") {
      const { code, output } = await probes.shell(need.check);
      results.push({
        id: need.id,
        ok: code === 0,
        detail: code === 0 ? need.why : `${need.why}: ${output.trim().split("\n").at(-1) ?? ""}`,
        fix: code === 0 ? undefined : need.fix,
      });
      continue;
    }
    if (need === "supabase") {
      const status = await probes.http(`${SUPABASE_URL}/rest/v1/`);
      results.push({
        id: need,
        ok: status !== null,
        detail:
          status !== null
            ? `local Supabase answers (${status})`
            : "local Supabase isn't answering on 127.0.0.1:54321",
        fix:
          status !== null
            ? undefined
            : `cd ${DATABASE_DIR} && npx supabase start`,
      });
      continue;
    }
    if (need === "embed-stub") {
      const status = await probes.http(EMBED_STUB_URL, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ input: ["ping"] }),
      });
      results.push({
        id: need,
        ok: status === 200,
        detail:
          status === 200
            ? "embeddings stub answers"
            : "the embeddings stub isn't answering on 127.0.0.1:3210",
        fix: status === 200 ? undefined : `python3 ${EMBED_STUB} &`,
      });
      continue;
    }
    const name = need.slice("env:".length);
    const set = Boolean(env[name]);
    results.push({
      id: need,
      ok: set,
      detail: set ? `${name} is set` : `${name} isn't set in this shell`,
      fix: set
        ? undefined
        : name.startsWith("SUPABASE_")
          ? EXPORT_DB_ENV
          : `export ${name}=...`,
    });
  }

  if (distDir) {
    const extensionJs = await probes.readFile(path.join(distDir, "extension.js"));
    if (extensionJs === null) {
      results.push({
        id: "dist",
        ok: false,
        detail: `no extension.js in ${distDir}`,
        fix: "Build the PR and copy the whole dist there, as the pr-video skill describes.",
      });
    } else {
      const bakes: Array<[string, string, string]> = [];
      if (ids.has("supabase")) {
        bakes.push([
          "127.0.0.1:54321",
          "the local database URL",
          "SUPABASE_USE_DB=implicit SUPABASE_URL=http://127.0.0.1:54321",
        ]);
      }
      if (ids.has("embed-stub")) {
        bakes.push([
          "127.0.0.1:3210",
          "the embeddings stub URL",
          "NEXT_API_ROOT=http://127.0.0.1:3210",
        ]);
      }
      for (const [needle, label, envHint] of bakes) {
        const baked = extensionJs.includes(needle);
        results.push({
          id: `dist:${needle}`,
          ok: baked,
          detail: baked
            ? `the dist has ${label} baked in`
            : `the dist doesn't have ${label} baked in`,
          fix: baked
            ? undefined
            : `Rebuild apps/roam with ${envHint} (see the pr-video skill), then copy the dist again.`,
        });
      }
      if (kit.target?.pr) {
        const built = buildCommitOf(extensionJs);
        const head = await probes.prHead(kit.target.pr);
        const fresh = Boolean(built && head && head.startsWith(built.slice(0, 7)));
        results.push({
          id: "dist:pr-head",
          ok: fresh || allowStaleBuild,
          detail:
            built && head
              ? fresh
                ? `the dist is PR #${kit.target.pr}'s head (${head.slice(0, 7)})`
                : `the dist was built from ${built.slice(0, 7)}, but PR #${kit.target.pr}'s head is ${head.slice(0, 7)}${allowStaleBuild ? " (allowed)" : ""}`
              : `couldn't compare the dist with PR #${kit.target.pr} (${built ? "no PR head from gh" : "no buildCommit in extension.js"})`,
          fix:
            fresh || allowStaleBuild
              ? undefined
              : "Rebuild from the PR's head and copy the dist again, or pass --allow-stale-build.",
        });
      }
    }
  }
  return results;
};

export const formatNeeds = (results: NeedResult[]): string =>
  results
    .map((result) =>
      result.ok
        ? `  ok    ${result.id}: ${result.detail}`
        : `  FAIL  ${result.id}: ${result.detail}\n        fix: ${result.fix ?? "see the kit"}`,
    )
    .join("\n");

