import { spawn } from "node:child_process";
import type { Page } from "playwright";
import type { Action } from "../recorder/recordDemo";
import type {
  Apply,
  Fixture,
  FixturePhase,
  Probe,
  RestProbe,
  RestWrite,
  Step,
  TestCase,
} from "./kit";
import { SUPABASE_URL } from "./needs";
import { fill, fillDeep, type TemplateContext } from "./template";

export type FixtureStatus = "kept" | "applied" | "missing" | "failed";

export type FixtureRun = {
  id: string;
  phase: FixturePhase;
  status: FixtureStatus;
  detail?: string;
};

// Where outside fixtures reach: the shell, the local REST API and psql inside
// the Supabase container. Tests swap in fakes.
export type OutsideRunner = {
  shell(command: string): Promise<{ code: number; output: string }>;
  rest(write: RestWrite | (RestProbe & { method: "GET" })): Promise<unknown>;
  sql(statement: string): Promise<{ code: number; output: string }>;
};

const SUPABASE_DB_CONTAINER = "supabase_db_discourse-graphs";

const run = (
  command: string,
  args: string[],
): Promise<{ code: number; output: string }> =>
  new Promise((resolve) => {
    const child = spawn(command, args, {
      stdio: ["ignore", "pipe", "pipe"],
      env: process.env,
    });
    let output = "";
    child.stdout.on("data", (chunk: Buffer) => {
      output += chunk.toString();
    });
    child.stderr.on("data", (chunk: Buffer) => {
      output += chunk.toString();
    });
    const timer = setTimeout(() => child.kill("SIGTERM"), 120_000);
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code: code ?? 1, output: output.slice(-4000) });
    });
  });

export const defaultOutsideRunner = (env: NodeJS.ProcessEnv): OutsideRunner => ({
  shell: (command) => run("/bin/sh", ["-c", command]),
  sql: (statement) =>
    run("docker", [
      "exec",
      SUPABASE_DB_CONTAINER,
      "psql",
      "-U",
      "postgres",
      "-d",
      "postgres",
      "-v",
      "ON_ERROR_STOP=1",
      "-c",
      statement,
    ]),
  rest: async (request) => {
    const key = env.SUPABASE_SERVICE_ROLE_KEY;
    if (!key) throw new Error("SUPABASE_SERVICE_ROLE_KEY isn't set.");
    const response = await fetch(`${SUPABASE_URL}${request.path}`, {
      method: request.method,
      headers: {
        apikey: key,
        authorization: `Bearer ${key}`,
        "content-type": "application/json",
        prefer: "return=representation",
      },
      body:
        "body" in request && request.body !== undefined
          ? JSON.stringify(request.body)
          : undefined,
    });
    const text = await response.text();
    if (!response.ok) {
      throw new Error(`${request.method} ${request.path} → ${response.status}: ${text.slice(0, 300)}`);
    }
    return text ? (JSON.parse(text) as unknown) : null;
  },
});

const describe = (error: unknown): string =>
  (error instanceof Error ? error.message : String(error)).slice(0, 600);

const probeOutside = async (
  check: Probe,
  runner: OutsideRunner,
  context: TemplateContext,
): Promise<boolean> => {
  if ("command" in check) {
    return (await runner.shell(fill(check.command, context))).code === 0;
  }
  if ("rest" in check) {
    const rows = await runner.rest({
      method: "GET",
      path: fill(check.rest.path, context),
      expect: check.rest.expect,
    });
    const count = Array.isArray(rows) ? rows.length : 0;
    return check.rest.expect === "rows" ? count > 0 : count === 0;
  }
  throw new Error("An outside check is { command } or { rest }.");
};

const applyOutside = async (
  apply: Apply,
  runner: OutsideRunner,
  context: TemplateContext,
): Promise<void> => {
  if ("command" in apply) {
    const { code, output } = await runner.shell(fill(apply.command, context));
    if (code !== 0) throw new Error(`exit ${code}: ${output.trim().slice(-300)}`);
    return;
  }
  if ("sql" in apply) {
    const { code, output } = await runner.sql(fill(apply.sql, context));
    if (code !== 0) throw new Error(`psql exit ${code}: ${output.trim().slice(-300)}`);
    return;
  }
  if ("rest" in apply) {
    await runner.rest(fillDeep(apply.rest, context));
    return;
  }
  throw new Error("An outside apply is { command }, { sql } or { rest }.");
};

const settle = async (
  fixture: Fixture,
  check: () => Promise<boolean>,
  apply: () => Promise<void>,
  checkOnly: boolean,
): Promise<FixtureRun> => {
  const base = { id: fixture.id, phase: fixture.phase };
  try {
    if (fixture.check && (await check())) return { ...base, status: "kept" };
    if (checkOnly) {
      return {
        ...base,
        status: "missing",
        detail: fixture.check ? fixture.why : "no check; it runs every time",
      };
    }
    await apply();
    if (fixture.check && !(await check())) {
      return {
        ...base,
        status: "failed",
        detail: `applied, but the check still fails: ${fixture.why}`,
      };
    }
    return { ...base, status: "applied" };
  } catch (error) {
    return { ...base, status: "failed", detail: describe(error) };
  }
};

export const runOutsideFixtures = async ({
  fixtures,
  runner,
  context,
  checkOnly,
}: {
  fixtures: Fixture[];
  runner: OutsideRunner;
  context: TemplateContext;
  checkOnly: boolean;
}): Promise<FixtureRun[]> => {
  const results: FixtureRun[] = [];
  for (const fixture of fixtures.filter((item) => item.phase === "outside")) {
    const result = await settle(
      fixture,
      () => probeOutside(fixture.check as Probe, runner, context),
      () => applyOutside(fixture.apply, runner, context),
      checkOnly,
    );
    results.push(result);
    if (result.status === "failed") break;
  }
  return results;
};

// Before-load fixtures run in a session without the extension, because the
// extension reads flags and node types once when it loads.
export const runPageFixtures = async ({
  page,
  fixtures,
  context,
  checkOnly,
}: {
  page: Page;
  fixtures: Fixture[];
  context: TemplateContext;
  checkOnly: boolean;
}): Promise<FixtureRun[]> => {
  const results: FixtureRun[] = [];
  for (const fixture of fixtures.filter((item) => item.phase === "before-load")) {
    const check = fixture.check;
    const apply = fixture.apply;
    const result = await settle(
      fixture,
      async () =>
        check && "js" in check
          ? Boolean(await page.evaluate(fill(check.js, context)))
          : false,
      async () => {
        if (!("js" in apply)) throw new Error("A before-load apply is { js }.");
        await page.evaluate(fill(apply.js, context));
      },
      checkOnly,
    );
    results.push(result);
    if (result.status === "failed") break;
  }
  return results;
};

export const settleMsFor = (fixtures: Fixture[], applied: FixtureRun[]): number => {
  const appliedIds = new Set(
    applied.filter((run) => run.status === "applied").map((run) => run.id),
  );
  const waits = fixtures
    .filter((fixture) => appliedIds.has(fixture.id))
    .map((fixture) => fixture.settleMs ?? 8000);
  return waits.length ? Math.max(...waits) : 0;
