    const timer = setTimeout(() => child.kill("SIGTERM"), 120_000);
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code: code ?? 1, output: output.slice(-4000) });
    });
  });

export const defaultOutsideRunner = (env: NodeJS.ProcessEnv): OutsideRunner => ({
  shell: (command) => run("/bin/sh", ["-c", command]),
  sql: (statement) =>
    run("docker", [
      "exec",
      SUPABASE_DB_CONTAINER,
      "psql",
      "-U",
      "postgres",
      "-d",
      "postgres",
      "-v",
      "ON_ERROR_STOP=1",
      "-c",
      statement,
    ]),
  rest: async (request) => {
    const key = env.SUPABASE_SERVICE_ROLE_KEY;
    if (!key) throw new Error("SUPABASE_SERVICE_ROLE_KEY isn't set.");
    const response = await fetch(`${SUPABASE_URL}${request.path}`, {
      method: request.method,
      headers: {
        apikey: key,
        authorization: `Bearer ${key}`,
        "content-type": "application/json",
        prefer: "return=representation",
      },
      body:
        "body" in request && request.body !== undefined
          ? JSON.stringify(request.body)
          : undefined,
    });
    const text = await response.text();
    if (!response.ok) {
      throw new Error(`${request.method} ${request.path} → ${response.status}: ${text.slice(0, 300)}`);
    }
    return text ? (JSON.parse(text) as unknown) : null;
  },
});

const describe = (error: unknown): string =>
  (error instanceof Error ? error.message : String(error)).slice(0, 600);

const probeOutside = async (
  check: Probe,
  runner: OutsideRunner,
  context: TemplateContext,
): Promise<boolean> => {
  if ("command" in check) {
    return (await runner.shell(fill(check.command, context))).code === 0;
  }
  if ("rest" in check) {
    const rows = await runner.rest({
      method: "GET",
      path: fill(check.rest.path, context),
      expect: check.rest.expect,
    });
    const count = Array.isArray(rows) ? rows.length : 0;
    return check.rest.expect === "rows" ? count > 0 : count === 0;
  }
  throw new Error("An outside check is { command } or { rest }.");
};

const applyOutside = async (
  apply: Apply,
  runner: OutsideRunner,
  context: TemplateContext,
): Promise<void> => {
  if ("command" in apply) {
    const { code, output } = await runner.shell(fill(apply.command, context));
    if (code !== 0) throw new Error(`exit ${code}: ${output.trim().slice(-300)}`);
    return;
  }
  if ("sql" in apply) {
    const { code, output } = await runner.sql(fill(apply.sql, context));
    if (code !== 0) throw new Error(`psql exit ${code}: ${output.trim().slice(-300)}`);
    return;
  }
  if ("rest" in apply) {
    await runner.rest(fillDeep(apply.rest, context));
    return;
  }
  throw new Error("An outside apply is { command }, { sql } or { rest }.");
};

const settle = async (
  fixture: Fixture,
  check: () => Promise<boolean>,
  apply: () => Promise<void>,
  checkOnly: boolean,
): Promise<FixtureRun> => {
  const base = { id: fixture.id, phase: fixture.phase };
  try {
    if (fixture.check && (await check())) return { ...base, status: "kept" };
    if (checkOnly) {
      return {
        ...base,
        status: "missing",
        detail: fixture.check ? fixture.why : "no check; it runs every time",
      };
    }
    await apply();
    if (fixture.check && !(await check())) {
      return {
        ...base,
        status: "failed",
        detail: `applied, but the check still fails: ${fixture.why}`,
      };
    }
    return { ...base, status: "applied" };
  } catch (error) {
    return { ...base, status: "failed", detail: describe(error) };
  }
};

export const runOutsideFixtures = async ({
  fixtures,
  runner,
  context,
  checkOnly,
}: {
  fixtures: Fixture[];
  runner: OutsideRunner;
  context: TemplateContext;
  checkOnly: boolean;
}): Promise<FixtureRun[]> => {
  const results: FixtureRun[] = [];
  for (const fixture of fixtures.filter((item) => item.phase === "outside")) {
    const result = await settle(
      fixture,
      () => probeOutside(fixture.check as Probe, runner, context),
      () => applyOutside(fixture.apply, runner, context),
      checkOnly,
    );
    results.push(result);
    if (result.status === "failed") break;
  }
  return results;
};

// Before-load fixtures run in a session without the extension, because the
// extension reads flags and node types once when it loads.
export const runPageFixtures = async ({
  page,
  fixtures,
  context,
  checkOnly,
}: {
  page: Page;
  fixtures: Fixture[];
  context: TemplateContext;
  checkOnly: boolean;
}): Promise<FixtureRun[]> => {
  const results: FixtureRun[] = [];
  for (const fixture of fixtures.filter((item) => item.phase === "before-load")) {
    const check = fixture.check;
    const apply = fixture.apply;
    const result = await settle(
      fixture,
      async () =>
        check && "js" in check
          ? Boolean(await page.evaluate(fill(check.js, context)))
          : false,
      async () => {
        if (!("js" in apply)) throw new Error("A before-load apply is { js }.");
        await page.evaluate(fill(apply.js, context));
      },
      checkOnly,
    );
    results.push(result);
    if (result.status === "failed") break;
  }
  return results;
};

export const settleMsFor = (fixtures: Fixture[], applied: FixtureRun[]): number => {
  const appliedIds = new Set(
    applied.filter((run) => run.status === "applied").map((run) => run.id),
  );
  const waits = fixtures
    .filter((fixture) => appliedIds.has(fixture.id))
    .map((fixture) => fixture.settleMs ?? 8000);
  return waits.length ? Math.max(...waits) : 0;
};

const wrapCheckApply = (fixture: Fixture, check: string | null, apply: string): string => {
  const label = JSON.stringify(`Fixture ${fixture.id} did not take: ${fixture.why}`);
  if (!check) {
    return `(async () => { await (${apply}); return "applied"; })()`;
  }
  return `(async () => {
  const present = async () => Boolean(await (${check}));
  if (await present()) return "kept";
  await (${apply});
  if (!(await present())) throw new Error(${label});
  return "applied";
})()`;
};

const assertStep = (check: string, label: string): string =>
  `(async () => { if (!(await (${check}))) throw new Error(${JSON.stringify(label)}); })()`;

// In-session fixtures become ordinary steps: a js fixture is one step that
// checks, applies and checks again; a UI fixture runs its steps every time,
// then asserts its check. Strings stay unfilled until they run.
export const inSessionSteps = (fixtures: Fixture[]): Step[] => {
  const steps: Step[] = [];
  for (const fixture of fixtures.filter((item) => item.phase === "in-session")) {
    const check = fixture.check && "js" in fixture.check ? fixture.check.js : null;
    if ("js" in fixture.apply) {
      steps.push({
        id: `fixture-${fixture.id}`,
        do: { js: wrapCheckApply(fixture, check, fixture.apply.js) },
        why: fixture.why,
        source: "kit",
      });
      continue;
    }
    if ("steps" in fixture.apply) {
      fixture.apply.steps.forEach((step, index) => {
        steps.push({ ...step, id: `fixture-${fixture.id}-${index + 1}`, source: "kit" });
      });
      if (check) {
        steps.push({
          id: `fixture-${fixture.id}-check`,
          do: { js: assertStep(check, `Fixture ${fixture.id} did not take: ${fixture.why}`) },
          why: `confirm ${fixture.why}`,
          source: "kit",
        });
      }
    }
  }
  return steps;
};

export const assertCase = (js: string, label: string): Action => ({
  js: `(async () => {
  try {
    await (${js});
  } catch (error) {
    throw new Error(${JSON.stringify(label)} + ": " + (error && error.message ? error.message : String(error)));
  }
})()`,
});

// Smoke cases are always-true checks from the baseline. They run as setup
// steps, so a broken environment fails fast and never reaches a PR case.
// Smoke checks that need your eyes (text only) can't run unattended.
export const smokeSteps = (smoke: TestCase[]): Step[] => {
  const steps: Step[] = [];
  for (const testCase of smoke) {
    if (testCase.steps.length === 0 && !testCase.expect?.js) continue;
    testCase.steps.forEach((step, index) => {
      steps.push({ ...step, id: `smoke-${testCase.id}-${index + 1}`, source: "kit" });
    });
    if (testCase.expect?.js) {
      steps.push({
        id: `smoke-${testCase.id}-check`,
        do: assertCase(testCase.expect.js, `Smoke check failed: ${testCase.title}`),
        why: `smoke: ${testCase.title}`,
        source: "kit",
      });
    }
  }
  return steps;
};

export const formatFixtures = (runs: FixtureRun[]): string =>
  runs
    .map(
      (fixture) =>
        `  ${fixture.status.padEnd(7)} ${fixture.phase.padEnd(11)} ${fixture.id}${fixture.detail ? `: ${fixture.detail}` : ""}`,
    )
    .join("\n");

