import { spawn } from "node:child_process";
import fsSync from "node:fs";
import fs from "node:fs/promises";
import path from "node:path";
import type { Action, Scene, Storyboard } from "../recorder/recordDemo";
import { assertCase, inSessionSteps, smokeSteps } from "./fixtures";
import {
  BASELINE_DIR,
  validateBaseline,
  validateKit,
  type Baseline,
  type Kit,
} from "./kit";
import { fillDeep, type TemplateContext } from "./template";

const RECORD_DEMO = path.resolve(__dirname, "../recorder/recordDemo.ts");

export type TakeReadiness = { blockers: string[]; unverified: string[] };

// A take runs with nobody at the screen, so it can't do what needs you: work
// out steps from an intent, or run js you haven't allowed. Cases checked only
// by eye still go in; the video is the evidence for them.
export const takeReadiness = (kit: Kit): TakeReadiness => {
  const blockers: string[] = [];
  const unverified: string[] = [];
  for (const testCase of kit.cases) {
    if (testCase.steps.length === 0) {
      blockers.push(
        `${testCase.id} "${testCase.title}" has no steps yet. Rehearse it live once, or write its steps.`,
      );
    }
    for (const step of testCase.steps) {
      if ("js" in step.do && (step.source ?? "kit") !== "kit" && !step.approved) {
        blockers.push(
          `${testCase.id} step ${step.id} is js from ${step.source === "you" ? "your instructions" : "the brain"} that you haven't allowed. Allow it in a live rehearsal first.`,
        );
      }
    }
    if (!testCase.expect?.js && testCase.expect?.text) {
      unverified.push(`${testCase.id} "${testCase.title}": ${testCase.expect.text}`);
    }
  }
  return { blockers, unverified };
};

export const buildTakeStoryboard = ({
  kit,
  baseline,
  sessionDir,
  distDir,
  context,
}: {
  kit: Kit;
  baseline: Baseline | null;
  sessionDir: string;
  distDir: string | null;
  context: TemplateContext;
}): Storyboard => {
  const fixtures = [...(baseline?.prepare ?? []), ...(kit.prepare ?? [])];
  const setup = [
    ...inSessionSteps(fixtures),
    ...smokeSteps(baseline?.smoke ?? []),
  ].map((step) => fillDeep(step.do, context));
  const scenes: Scene[] = kit.cases.map((testCase) => {
    const actions: Action[] = testCase.steps.map((step) =>
      fillDeep(step.do, context),
    );
    if (testCase.expect?.js) {
      actions.push(
        fillDeep(
          assertCase(testCase.expect.js, `Case ${testCase.id} failed`),
          context,
        ),
      );
    }
    const scene: Scene = { name: `${testCase.id}: ${testCase.title}`, do: actions };
    if (testCase.caption) scene.caption = fillDeep(testCase.caption, context);
    if (testCase.toast) scene.toast = fillDeep(testCase.toast, context);
    return scene;
  });
  const storyboard: Storyboard = {
    output: path.join(sessionDir, `${kit.name}.webm`),
    viewport: kit.target?.viewport ?? { width: 1280, height: 720 },
    setup,
    scenes,
  };
  if (distDir) storyboard.dist = distDir;
  return storyboard;
};

export type TakeModuleOptions = {
  kitFile: string;
  baselineDir?: string;
  sessionDir: string;
  distDir: string | null;
  run: string;
};

// recordDemo imports storyboards synchronously, so the generated module reads
// the kit with sync calls and fills env values from its own process env.
export const storyboardFromFileSync = ({
  kitFile,
  baselineDir = BASELINE_DIR,
  sessionDir,
  distDir,
  run,
}: TakeModuleOptions): Storyboard => {
  const kit = validateKit(JSON.parse(fsSync.readFileSync(kitFile, "utf8")));
  const baseline = kit.baseline
    ? validateBaseline(
        JSON.parse(
          fsSync.readFileSync(path.join(baselineDir, `${kit.baseline}.json`), "utf8"),
        ),
      )
    : null;
  return buildTakeStoryboard({
    kit,
    baseline,
    sessionDir,
    distDir,
    context: { env: process.env, kit: kit.name, run },
  });
};

export const takeModuleSource = (options: TakeModuleOptions): string =>
  [
    "// Generated by proof/take.ts for one take. It builds the storyboard when",
    "// recordDemo loads it, so env values are filled in memory, never on disk.",
    `import { storyboardFromFileSync } from ${JSON.stringify(path.join(__dirname, "take"))};`,
    "",
    `export default storyboardFromFileSync(${JSON.stringify(options, null, 2)});`,
    "",
  ].join("\n");

export type SceneStart = { index: number; total: number; name: string };

export type TakeOutcome = {
  code: number;
  scenes: SceneStart[];
  video: string | null;
  failedVideo: string | null;
  errorTail: string;
};

export const parseRecordDemoOutput = (
  stdout: string,
  stderr: string,
  code: number,
): TakeOutcome => ({
  code,
  scenes: [...stdout.matchAll(/\[recordDemo\] Scene (\d+)\/(\d+): ?(.*)/g)].map(
    (match) => ({
      index: Number(match[1]),
      total: Number(match[2]),
      name: match[3].trim(),
    }),
  ),
  video: /\[recordDemo\] Demo video: (.+)/.exec(stdout)?.[1].trim() ?? null,
  failedVideo:
    /\[recordDemo\] Failed-run video: (.+)/.exec(stdout)?.[1].trim() ?? null,
  errorTail: stderr.split("\n").filter(Boolean).slice(-20).join("\n"),
});

export type TakeCaseResult = {
  id: string;
  title: string;
  result: "pass" | "fail" | "shown" | "not run";
  note?: string;
};

const firstMatch = (text: string, pattern: RegExp): string | null =>
  pattern.exec(text)?.[0].trim() ?? null;

export const takeResults = (
  kit: Kit,
  outcome: TakeOutcome,
): { setupFailure: string | null; cases: TakeCaseResult[] } => {
  const settled = (index: number): TakeCaseResult => {
    const testCase = kit.cases[index];
    const shown = !testCase.expect?.js && Boolean(testCase.expect?.text);
    return { id: testCase.id, title: testCase.title, result: shown ? "shown" : "pass" };
  };
  if (outcome.code === 0) {
    return { setupFailure: null, cases: kit.cases.map((_, index) => settled(index)) };
  }
  const notRun = (index: number): TakeCaseResult => ({
    id: kit.cases[index].id,
    title: kit.cases[index].title,
    result: "not run",
  });
  const started = outcome.scenes.length;
  if (started === 0) {
    return {
      setupFailure:
        firstMatch(outcome.errorTail, /(Fixture|Smoke check failed)[^\n]*/) ??
        outcome.errorTail.split("\n").at(-1) ??
        "recordDemo failed before the first scene.",
      cases: kit.cases.map((_, index) => notRun(index)),
    };
  }
  const failedIndex = Math.min(started, kit.cases.length) - 1;
  const caseFailure = new RegExp(`Case ${kit.cases[failedIndex].id} failed: [^\\n]*`);
  return {
    setupFailure: null,
    cases: kit.cases.map((testCase, index) => {
      if (index < failedIndex) return settled(index);
      if (index > failedIndex) return notRun(index);
      return {
        id: testCase.id,
        title: testCase.title,
        result: "fail",
        note:
          firstMatch(outcome.errorTail, caseFailure) ??
          outcome.errorTail.split("\n").find((line) => /Error/.test(line))?.trim() ??
          "the take stopped in this case",
      };
    }),
  };
};

export const renderTakeReport = ({
  kit,
  results,
  outcome,
  graph,
  dist,
  session,
  preparation,
  environment,
}: {
  kit: Kit;
  results: { setupFailure: string | null; cases: TakeCaseResult[] };
  outcome: TakeOutcome;
  graph: string;
  dist: string | null;
  session: string;
  preparation: string;
  environment: string;
}): string => {
  const checked = results.cases.filter((item) => item.result !== "shown");
  const passed = checked.filter((item) => item.result === "pass").length;
  const lines = [
    `### Proof: ${kit.title ?? kit.name}`,
    "",
    [
      `\`${kit.name}\``,
      graph,
      dist ? `build \`${dist}\`` : "no extension",
      new Date().toISOString().slice(0, 10),
      `${passed}/${checked.length} checked cases passed`,
    ].join(" · "),
    "",
  ];
  if (results.setupFailure) {
    lines.push(`Setup failed before the first case: ${results.setupFailure}`, "");
  }
  for (const item of results.cases) {
    const box = item.result === "pass" ? "[x]" : "[ ]";
    const word =
      item.result === "shown" ? "shown in the video, check it there" : item.result;
    lines.push(`- ${box} **${item.title}**: ${word}${item.note ? `. ${item.note}` : ""}`);
  }
  lines.push("");
  if (outcome.video) lines.push(`Video: \`${outcome.video}\``, "");
  if (outcome.failedVideo) lines.push(`Failed take: \`${outcome.failedVideo}\``, "");
  lines.push(
    `<details><summary>Preparation</summary>\n\n\`\`\`text\n${preparation || "(nothing to prepare)"}\n\`\`\`\n\n</details>`,
    `<details><summary>Environment</summary>\n\n\`\`\`text\n${environment || "(no needs)"}\n\`\`\`\n\n</details>`,
    "",
    `<sub>Session ${session}</sub>`,
    "",
  );
  return lines.join("\n");
};

const tsxCommand = (): { command: string; prefix: string[] } => {
  const local = path.join(process.cwd(), "node_modules", ".bin", "tsx");
  return fsSync.existsSync(local)
    ? { command: local, prefix: [] }
    : { command: "npx", prefix: ["tsx"] };
};

export const recordTake = async ({
  modulePath,
  slot,
  url,
  hasDist,
  narrate,
  cursor,
  voice,
  timeout,
}: {
  modulePath: string;
  slot: string;
  url: string;
  hasDist: boolean;
  narrate: boolean;
  cursor: boolean;
  voice?: string;
  timeout: number;
}): Promise<TakeOutcome> => {
  const args = [
    RECORD_DEMO,
    "--storyboard",
    modulePath,
    "--slot",
    slot,
    "--url",
    url,
    "--timeout",
    String(timeout),
  ];
  if (!hasDist) args.push("--no-extension");
  if (narrate) args.push("--narrate");
  if (voice) args.push("--voice", voice);
  if (cursor) args.push("--cursor");
  const { command, prefix } = tsxCommand();
  return new Promise((resolve) => {
    const child = spawn(command, [...prefix, ...args], {
      cwd: process.cwd(),
      env: process.env,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
      process.stdout.write(chunk);
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
      process.stderr.write(chunk);
    });
    child.on("close", (code) => {
      resolve(parseRecordDemoOutput(stdout, stderr, code ?? 1));
    });
  });
};

export const writeTakeModule = async (
  options: TakeModuleOptions,
): Promise<string> => {
  const modulePath = path.join(options.sessionDir, "take.storyboard.ts");
  await fs.writeFile(modulePath, takeModuleSource(options));
  return modulePath;
};

