  video: string | null;
  failedVideo: string | null;
  errorTail: string;
};

export const parseRecordDemoOutput = (
  stdout: string,
  stderr: string,
  code: number,
): TakeOutcome => ({
  code,
  scenes: [...stdout.matchAll(/\[recordDemo\] Scene (\d+)\/(\d+): ?(.*)/g)].map(
    (match) => ({
      index: Number(match[1]),
      total: Number(match[2]),
      name: match[3].trim(),
    }),
  ),
  video: /\[recordDemo\] Demo video: (.+)/.exec(stdout)?.[1].trim() ?? null,
  failedVideo:
    /\[recordDemo\] Failed-run video: (.+)/.exec(stdout)?.[1].trim() ?? null,
  errorTail: stderr.split("\n").filter(Boolean).slice(-20).join("\n"),
});

