  pattern.exec(text)?.[0].trim() ?? null;

export const takeResults = (
  kit: Kit,
  outcome: TakeOutcome,
): { setupFailure: string | null; cases: TakeCaseResult[] } => {
  const settled = (index: number): TakeCaseResult => {
    const testCase = kit.cases[index];
    const shown = !testCase.expect?.js && Boolean(testCase.expect?.text);
    return { id: testCase.id, title: testCase.title, result: shown ? "shown" : "pass" };
  };
  if (outcome.code === 0) {
    return { setupFailure: null, cases: kit.cases.map((_, index) => settled(index)) };
  }
  const notRun = (index: number): TakeCaseResult => ({
    id: kit.cases[index].id,
    title: kit.cases[index].title,
    result: "not run",
