        "recordDemo failed before the first scene.",
      cases: kit.cases.map((_, index) => notRun(index)),
    };
  }
  const failedIndex = Math.min(started, kit.cases.length) - 1;
  const caseFailure = new RegExp(`Case ${kit.cases[failedIndex].id} failed: [^\\n]*`);
