  graph: string;
  dist: string | null;
  session: string;
  preparation: string;
  environment: string;
}): string => {
  const checked = results.cases.filter((item) => item.result !== "shown");
  const passed = checked.filter((item) => item.result === "pass").length;
  const lines = [
    `### Proof: ${kit.title ?? kit.name}`,
    "",
