      `\`${kit.name}\``,
      graph,
      dist ? `build \`${dist}\`` : "no extension",
      new Date().toISOString().slice(0, 10),
      `${passed}/${checked.length} checked cases passed`,
    ].join(" · "),
    "",
  ];
  if (results.setupFailure) {
    lines.push(`Setup failed before the first case: ${results.setupFailure}`, "");
  }
  for (const item of results.cases) {
    const box = item.result === "pass" ? "[x]" : "[ ]";
    const word =
      item.result === "shown" ? "shown in the video, check it there" : item.result;
    lines.push(`- ${box} **${item.title}**: ${word}${item.note ? `. ${item.note}` : ""}`);
  }
