  if (outcome.failedVideo) lines.push(`Failed take: \`${outcome.failedVideo}\``, "");
  lines.push(
    `<details><summary>Preparation</summary>\n\n\`\`\`text\n${preparation || "(nothing to prepare)"}\n\`\`\`\n\n</details>`,
    `<details><summary>Environment</summary>\n\n\`\`\`text\n${environment || "(no needs)"}\n\`\`\`\n\n</details>`,
    "",
    `<sub>Session ${session}</sub>`,
    "",
  );
  return lines.join("\n");
};

const tsxCommand = (): { command: string; prefix: string[] } => {
  const local = path.join(process.cwd(), "node_modules", ".bin", "tsx");
  return fsSync.existsSync(local)
    ? { command: local, prefix: [] }
    : { command: "npx", prefix: ["tsx"] };
};

export const recordTake = async ({
  modulePath,
  slot,
  url,
  hasDist,
  narrate,
  cursor,
  voice,
  timeout,
}: {
  modulePath: string;
  slot: string;
  url: string;
  hasDist: boolean;
  narrate: boolean;
  cursor: boolean;
  voice?: string;
  timeout: number;
}): Promise<TakeOutcome> => {
  const args = [
    RECORD_DEMO,
    "--storyboard",
    modulePath,
    "--slot",
    slot,
    "--url",
    url,
    "--timeout",
    String(timeout),
  ];
  if (!hasDist) args.push("--no-extension");
  if (narrate) args.push("--narrate");
  if (voice) args.push("--voice", voice);
  if (cursor) args.push("--cursor");
  const { command, prefix } = tsxCommand();
  return new Promise((resolve) => {
    const child = spawn(command, [...prefix, ...args], {
      cwd: process.cwd(),
      env: process.env,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString();
      process.stdout.write(chunk);
    });
    child.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString();
      process.stderr.write(chunk);
    });
    child.on("close", (code) => {
      resolve(parseRecordDemoOutput(stdout, stderr, code ?? 1));
    });
  });
};

