import { fill, fillDeep, type TemplateContext } from "./template";

const ARIA_LIMIT = 40_000;
const TEXT_LIMIT = 20_000;
const QUERY_LIMIT = 50_000;
const CONSOLE_LIMIT = 200;

const clip = (value: string, limit: number): string =>
  value.length > limit
    ? `${value.slice(0, limit)}\n… (${value.length - limit} more characters)`
    : value;

const toNumber = (value: unknown, fallback: number): number => {
  const parsed = Number(value);
  return value !== undefined && value !== "" && Number.isFinite(parsed)
    ? parsed
    : fallback;
};

export type LiveOptions = {
  kit: Kit;
  original: Kit;
  baseline: Baseline | null;
  target: ProofTarget;
  distDir: string | null;
  viewport: { width: number; height: number };
  dpr: number;
  cursor: boolean;
  allowLogin: boolean;
  timeout: number;
  mode: Mode;
  speed: number;
  dwellMs: number;
  sessionDir: string;
  session: string;
  journal: Journal;
  context: TemplateContext;
  log: (message: string) => void;
};

export type LiveResult = {
  reportPath: string;
  proposedPath: string;
  footage: string | null;
};

// A rehearsal: the kit's cases run in front of you, you steer from the HUD,
// and the brain works through the control socket. It ends only when you press
// Stop or the brain sends stop.
export const runLive = async (options: LiveOptions): Promise<LiveResult> => {
  const { kit, journal, context, log, sessionDir } = options;
  const nonce = crypto.randomBytes(16).toString("hex");
  const videoDir = path.join(sessionDir, "video");
  const consoleAll: string[] = [];
  const consoleUnread: string[] = [];
  const recordConsole = (line: string): void => {
    for (const list of [consoleAll, consoleUnread]) {
      list.push(line.slice(0, 1000));
      if (list.length > CONSOLE_LIMIT) list.shift();
    }
  };

  let page: Page | null = null;
  let machine: Machine | null = null;
  const proofSession = await openProofSession({
    target: options.target,
    viewport: options.viewport,
    dpr: options.dpr,
    distDir: options.distDir,
    cursor: options.cursor,
    recordDir: videoDir,
    allowLogin: options.allowLogin,
    timeout: options.timeout,
    initScripts: [buildHudScript(nonce)],
    beforeNavigate: async (browserContext) => {
      await browserContext.exposeBinding(
        HUD_BINDING,
        makeHudHandler({
          nonce,
          isMainFrame: (frame) => page !== null && frame === page.mainFrame(),
          command: (cmd, args) =>
            machine
              ? machine.command("hud", cmd, args)
              : { ok: false, error: "The runner is still starting." },
        }),
      );
    },
  });
  const livePage = proofSession.page;
  page = livePage;
  livePage.on("console", (message) => {
    if (message.type() === "error") {
      recordConsole(`[console.error] ${message.text()}`);
    }
  });
  livePage.on("pageerror", (error) => recordConsole(`[pageerror] ${error.message}`));
  log("Roam is ready.");

  const executor: Executor = {
    run: (action) =>
      runAction({
        page: livePage,
        action: fillDeep(action, context),
        timeout: options.timeout,
        outDir: sessionDir,
        cursor: options.cursor,
      }),
    check: async (js) => {
      await livePage.evaluate(fill(js, context));
    },
    snapshot: async () =>
      clip(
        await livePage.locator("body").ariaSnapshot({ timeout: 5000 }),
        ARIA_LIMIT,
      ),
    render: async (state) => {
      await livePage.evaluate(
        `window.__dgHud && window.__dgHud.render(${JSON.stringify(state)})`,
      );
    },
  };

  const writeOutputs = async (): Promise<{
    reportPath: string;
    proposedPath: string;
  }> => {
    const live = machine as Machine;
    const events = journal.all();
    const baked = bakeKit({
      working: kit,
      events,
      session: options.session,
      results: live.results,
      notes: live.notes,
    });
    const proposedPath = path.join(sessionDir, "kit.proposed.json");
    await saveKit(proposedPath, baked);
    const reportPath = path.join(sessionDir, "report.md");
    await fs.writeFile(
      reportPath,
      renderReport({
        original: options.original,
        baked,
        events,
        session: options.session,
        results: live.results,
        notes: live.notes,
        graph: options.target.graph,
        dist: options.distDir ? path.basename(options.distDir) : null,
        consoleLines: consoleAll,
      }),
    );
    return { reportPath, proposedPath };
  };

  const fixtures = [...(options.baseline?.prepare ?? []), ...(kit.prepare ?? [])];
  machine = new Machine({
    kit,
    setup: [...inSessionSteps(fixtures), ...smokeSteps(options.baseline?.smoke ?? [])],
    journal,
    executor,
    mode: options.mode,
    speed: options.speed,
    dwellMs: options.dwellMs,
    origin: new URL(options.target.slotConfig.graphUrl).origin,
    stayOpen: true,
    onIdle: async () => {
      const { reportPath } = await writeOutputs();
      log(`Every case has a verdict. Interim report: ${reportPath}`);
    },
  });
  const live = machine;

  let server: ControlServer | null = null;
  try {
    server = await startControlServer({
      socketPath: defaultSocketPath(),
      handle: async (cmd, args) => {
        switch (cmd) {
          case "events": {
            const since = toNumber(args.since, 0);
            const waitMs = Math.min(Math.max(toNumber(args.waitMs, 0), 0), 30_000);
            const events = await journal.wait(since, waitMs);
            return { events, lastSeq: journal.lastSeq };
          }
          case "query": {
            if (typeof args.q !== "string" || !args.q.trim()) {
              throw new Error('query needs "q", a Datalog query string.');
            }
            const result = await livePage.evaluate(
              `JSON.stringify(window.roamAlphaAPI.q(${JSON.stringify(args.q)}))`,
            );
            return clip(String(result), QUERY_LIMIT);
          }
          case "aria": {
            const selector =
              typeof args.selector === "string" && args.selector ? args.selector : "body";
            return clip(
              await livePage.locator(selector).first().ariaSnapshot({ timeout: 5000 }),
              ARIA_LIMIT,
            );
          }
          case "text": {
            if (typeof args.selector !== "string" || !args.selector) {
              throw new Error('text needs a "selector".');
            }
            const texts = await livePage.locator(args.selector).allInnerTexts();
            return clip(texts.slice(0, 50).join("\n---\n"), TEXT_LIMIT);
          }
          case "screenshot": {
            const name = typeof args.name === "string" ? args.name : "";
            if (!SCREENSHOT_NAME.test(name)) {
              throw new Error("screenshot needs a file name with no slashes.");
            }
            const file = path.join(
              sessionDir,
              name.endsWith(".png") ? name : `${name}.png`,
            );
            await livePage.screenshot({ path: file });
            return file;
          }
          case "console":
            return consoleUnread.splice(0, consoleUnread.length);
          default: {
            const result = live.command("socket", cmd, args);
            if (!result.ok) throw new Error(result.error);
            return result.value;
          }
        }
      },
    });

    const requestStop = (): void => {
      log("Stopping.");
      live.stop();
    };
    process.once("SIGINT", requestStop);
    process.once("SIGTERM", requestStop);

    log(`PROOF READY ${server.socketPath}`);
    await live.run();
    const outputs = await writeOutputs();
    const footage = await finish(proofSession, videoDir, sessionDir);
    return { ...outputs, footage };
  } catch (error) {
    await finish(proofSession, videoDir, sessionDir);
    throw error;
  } finally {
    if (server) await server.close().catch(() => undefined);
  }
};

const finish = async (
  proofSession: { close(): Promise<string | null> },
  videoDir: string,
  sessionDir: string,
): Promise<string | null> => {
  const raw = await proofSession.close().catch(() => null);
  let footage: string | null = null;
  if (raw) {
    footage = path.join(sessionDir, "session.webm");
    await fs.rename(raw, footage).catch(() => {
      footage = null;
    });
  }
  await fs.rm(videoDir, { recursive: true, force: true }).catch(() => undefined);
  return footage;
};

