/**
 * Prove a PR with its proof kit. Run from discourse-graph/apps/roam (for its
 * tsx and playwright):
 *
 *   npx tsx /mnt/data/projects/dg-demo-videos/proof/prove.ts --kit <file> [mode] [flags]
 *
 * Modes:
 *   (default)           Record the narrated video (a take) from the kit.
 *   --live              Rehearse it in front of you, steered from the HUD and chat.
 *   --check             Report what's missing and change nothing.
 *
 * Every mode first checks the kit's needs, then prepares only the data whose
 * check fails: outside fixtures from the shell, then before-load fixtures in a
 * session without the extension (verified in a fresh session). In-session
 * fixtures and the baseline's smoke checks run at the start of the session.
 *
 * Flags:
 *   --dist <dir>          Extension dist (overrides target.dist).
 *   --no-extension        Run without loading a dist.
 *   --slot <1|2|3>        Playwright profile slot (default target.slot, else 3).
 *   --url <graph-url>     Override the slot's graph URL.
 *   --allow-dev-graph     Allow discourse-dev-graph; refused by default.
 *   --allow-login         Wait for a manual login if the profile is logged out.
 *   --allow-stale-build   Run even if the dist isn't the PR's head commit.
 *   --mode <m>            Live only: auto (default), step or case.
 *   --speed <x>           Live only: 0.25 to 4 (default 1).
 *   --dwell <ms>          Live only: hold after each step (default 1200).
 *   --no-narrate          Take only: skip the Kokoro narration.
 *   --voice <name>        Take only: Kokoro voice.
 *   --dpr <n>             Device scale factor (default target.dpr, else 2).
 *   --no-cursor           Don't draw the cursor overlay.
 *   --out <dir>           Session folder root (default dg-demo-videos/output/proof).
 *   --timeout <ms>        Default step timeout (default 45000).
 */
import fs from "node:fs/promises";
import path from "node:path";
import {
  getBooleanArg,
  getStringArg,
  parseArgs,
  timestamp,
} from "../../discourse-graph/apps/roam/scripts/playwright/roamSession";
import {
  defaultOutsideRunner,
  formatFixtures,
  runOutsideFixtures,
  runPageFixtures,
  settleMsFor,
  type FixtureRun,
} from "./fixtures";
import { Journal } from "./journal";
import { loadBaseline, loadKit, type Baseline, type Kit } from "./kit";
import { runLive } from "./live";
import { MAX_SPEED, MIN_SPEED, type Mode } from "./machine";
import { checkNeeds, formatNeeds } from "./needs";
import { openProofSession, resolveTarget, type ProofTarget } from "./session";
import {
  recordTake,
  renderTakeReport,
  storyboardFromFileSync,
  takeReadiness,
  takeResults,
  writeTakeModule,
} from "./take";
import type { TemplateContext } from "./template";

const log = (message: string): void => console.log(`[proof] ${message}`);

const numberArg = (value: string | undefined, fallback: number): number => {
  const parsed = Number(value);
  return value !== undefined && value !== "" && Number.isFinite(parsed)
    ? parsed
    : fallback;
};

const prepareBeforeLoad = async ({
  kit,
  baseline,
  target,
  viewport,
  dpr,
  allowLogin,
  timeout,
  context,
  checkOnly,
}: {
  kit: Kit;
  baseline: Baseline | null;
  target: ProofTarget;
  viewport: { width: number; height: number };
  dpr: number;
  allowLogin: boolean;
  timeout: number;
  context: TemplateContext;
  checkOnly: boolean;
}): Promise<FixtureRun[]> => {
  const fixtures = [...(baseline?.prepare ?? []), ...(kit.prepare ?? [])].filter(
    (fixture) => fixture.phase === "before-load",
  );
  if (fixtures.length === 0) return [];
  const open = () =>
    openProofSession({
      target,
      viewport,
      dpr,
      distDir: null,
      cursor: false,
      allowLogin,
      timeout,
    });
  log(`Checking ${fixtures.length} before-load fixture(s) without the extension.`);
  let session = await open();
  let runs: FixtureRun[];
  try {
    runs = await runPageFixtures({ page: session.page, fixtures, context, checkOnly });
    const settleMs = settleMsFor(fixtures, runs);
    if (settleMs > 0) {
      log(`Letting Roam sync the writes for ${settleMs} ms.`);
      await session.page.waitForTimeout(settleMs);
    }
  } finally {
    await session.close();
  }
  if (checkOnly || !runs.some((run) => run.status === "applied")) return runs;
  log("Verifying the before-load writes in a fresh session.");
  session = await open();
  try {
    const verified = await runPageFixtures({
      page: session.page,
      fixtures,
      context,
      checkOnly: true,
    });
    return runs.map((run) => {
      const after = verified.find((item) => item.id === run.id);
      return run.status === "applied" && after?.status !== "kept"
        ? {
            ...run,
            status: "failed",
            detail: "applied, but a fresh session doesn't see it",
          }
        : run;
    });
  } finally {
    await session.close();
  }
};

const main = async (): Promise<void> => {
  const args = parseArgs(process.argv.slice(2));
  const kitArg = getStringArg(args, "kit");
  if (!kitArg) throw new Error("--kit <file> is required.");
  const kitFile = path.resolve(kitArg);
  const kit = await loadKit(kitFile);
  const original = structuredClone(kit);
  const baseline = kit.baseline ? await loadBaseline(kit.baseline) : null;
  const target = kit.target ?? {};

  const live = getBooleanArg(args, "live");
  const checkOnly = getBooleanArg(args, "check");
  if (live && checkOnly) throw new Error("Pick one: --live or --check.");
  const mode = (getStringArg(args, "mode") || "auto") as Mode;
  if (!["auto", "step", "case"].includes(mode)) {
    throw new Error("--mode must be auto, step or case.");
  }
  const speed = numberArg(getStringArg(args, "speed"), 1);
  if (speed < MIN_SPEED || speed > MAX_SPEED) {
    throw new Error(`--speed must be between ${MIN_SPEED} and ${MAX_SPEED}.`);
  }
  const dwellMs = numberArg(getStringArg(args, "dwell"), 1200);
  const timeout = numberArg(getStringArg(args, "timeout"), 45_000);
  const viewport = target.viewport ?? { width: 1280, height: 720 };
  const dpr = numberArg(getStringArg(args, "dpr"), target.dpr ?? 2);
  const cursor = !getBooleanArg(args, "no-cursor");
  const allowLogin = getBooleanArg(args, "allow-login");

  const skipExtension = getBooleanArg(args, "no-extension");
  const distArg = getStringArg(args, "dist") || target.dist;
  if (!skipExtension && !distArg) {
    throw new Error(
      "Pass --dist <dir>, set target.dist in the kit, or pass --no-extension.",
    );
  }
  const distDir = skipExtension || !distArg ? null : path.resolve(distArg);

  const proofTarget = resolveTarget({
    slot: getStringArg(args, "slot") || target.slot,
    url: getStringArg(args, "url") || target.url,
    allowDevGraph: getBooleanArg(args, "allow-dev-graph"),
  });

  const run = timestamp();
  const session = `${kit.name}-${run}`;
  const outRoot = path.resolve(
    getStringArg(args, "out") || path.join(__dirname, "..", "output", "proof"),
  );
  const sessionDir = path.join(outRoot, session);
  await fs.mkdir(sessionDir, { recursive: true });
  const journal = new Journal(path.join(sessionDir, "journal.jsonl"));
  const context: TemplateContext = { env: process.env, kit: kit.name, run };
  const modeName = checkOnly ? "check" : live ? "live" : "take";
  journal.append("proof-start", {
    kit: kit.name,
    mode: modeName,
    graph: proofTarget.graph,
    dist: distDir,
  });
  log(`Kit ${kit.name} (${modeName}) on ${proofTarget.graph}, slot ${proofTarget.slotConfig.slot}.`);
  log(`Session: ${sessionDir}`);

  const needs = await checkNeeds({
    kit,
    baseline,
    distDir,
    allowStaleBuild: getBooleanArg(args, "allow-stale-build"),
  });
  const environment = formatNeeds(needs);
  journal.append("needs", { results: needs });
  if (needs.length) log(`Needs:\n${environment}`);
  const missing = needs.filter((need) => !need.ok);
  if (missing.length > 0) {
    journal.append("proof-end", { ok: false, reason: "needs" });
    throw new Error(
      `${missing.length} need(s) aren't met. Run the fix lines above, then rerun.`,
    );
  }

  if (!live && !checkOnly) {
    const readiness = takeReadiness(kit);
    if (readiness.blockers.length > 0) {
      journal.append("proof-end", { ok: false, reason: "not-ready", blockers: readiness.blockers });
      throw new Error(
        `This kit isn't ready for an unattended take:\n- ${readiness.blockers.join("\n- ")}\nRehearse it with --live first.`,
      );
    }
    for (const line of readiness.unverified) {
      log(`Checked by eye only, the video is the evidence: ${line}`);
    }
  }

  const fixtures = [...(baseline?.prepare ?? []), ...(kit.prepare ?? [])];
  const outside = await runOutsideFixtures({
    fixtures,
    runner: defaultOutsideRunner(process.env),
    context,
    checkOnly,
  });
  const beforeLoad = outside.some((item) => item.status === "failed")
    ? []
    : await prepareBeforeLoad({
        kit,
        baseline,
        target: proofTarget,
        viewport,
        dpr,
        allowLogin,
        timeout,
        context,
        checkOnly,
      });
  const prepared = [...outside, ...beforeLoad];
  const preparation = formatFixtures(prepared);
  journal.append("fixtures", { results: prepared });
  if (prepared.length) log(`Preparation:\n${preparation}`);
  if (prepared.some((item) => item.status === "failed")) {
    journal.append("proof-end", { ok: false, reason: "fixtures" });
    throw new Error("A fixture failed. Fix it in the kit, then rerun.");
  }
  if (checkOnly) {
    const pending = prepared.filter((item) => item.status === "missing");
    log(
      pending.length
        ? `${pending.length} fixture(s) would run. Everything else is in place.`
        : "Everything the kit checks is in place.",
    );
    journal.append("proof-end", { ok: true, mode: "check" });
    return;
  }

  if (live) {
    const result = await runLive({
      kit,
      original,
      baseline,
      target: proofTarget,
      distDir,
      viewport,
      dpr,
      cursor,
      allowLogin,
      timeout,
      mode,
      speed,
      dwellMs,
      sessionDir,
      session,
      journal,
      context,
      log,
    });
    journal.append("proof-end", { ok: true, mode: "live" });
    log(`Report: ${result.reportPath}`);
    log(`Proposed kit: ${result.proposedPath}`);
    log(`Review it with: diff -u ${kitFile} ${result.proposedPath}`);
    if (result.footage) log(`Footage: ${result.footage}`);
    return;
  }

  const moduleOptions = { kitFile, sessionDir, distDir, run };
  storyboardFromFileSync(moduleOptions);
  const modulePath = await writeTakeModule(moduleOptions);
  log(`Recording the take (${kit.cases.length} case(s)).`);
  const outcome = await recordTake({
    modulePath,
    slot: proofTarget.slotConfig.slot,
    url: proofTarget.slotConfig.graphUrl,
    hasDist: distDir !== null,
    narrate: !getBooleanArg(args, "no-narrate"),
    cursor,
    voice: getStringArg(args, "voice"),
    timeout,
  });
  const results = takeResults(kit, outcome);
  journal.append("take-end", { outcome, results });
  const reportPath = path.join(sessionDir, "report.md");
  await fs.writeFile(
    reportPath,
    renderTakeReport({
      kit,
      results,
      outcome,
      graph: proofTarget.graph,
      dist: distDir ? path.basename(distDir) : null,
      session,
      preparation,
      environment,
    }),
  );
  const ok =
    outcome.code === 0 && results.cases.every((item) => item.result !== "fail");
  journal.append("proof-end", { ok, mode: "take" });
  log(`Report: ${reportPath}`);
  if (outcome.video) log(`Video: ${outcome.video}`);
  if (!ok) {
    throw new Error(
      results.setupFailure
        ? `Setup failed: ${results.setupFailure}`
        : results.recordingFailure
          ? `The video failed to assemble: ${results.recordingFailure}`
          : "A case failed. See the report.",
    );
  }
};

if (require.main === module) {
  main().catch((error: unknown) => {
    console.error(
      `[proof] ${error instanceof Error ? error.message : String(error)}`,
    );
    process.exit(1);
  });
}

