import assert from "node:assert/strict";
import test from "node:test";
import {
  inSessionSteps,
  runOutsideFixtures,
  smokeSteps,
  type OutsideRunner,
} from "../fixtures";
import { validateBaseline, validateFixtures } from "../kit";

const context = { env: {}, kit: "k", run: "r" };

const fakeRunner = () => {
  const calls: string[] = [];
  const state = { rows: 0 };
  const runner: OutsideRunner = {
    shell: async (command) => {
      calls.push(`shell ${command}`);
      return { code: command.includes("fail") ? 1 : 0, output: "" };
    },
    sql: async (statement) => {
      calls.push(`sql ${statement}`);
      if (!statement.includes("noop")) state.rows += 1;
      return { code: 0, output: "INSERT 0 1" };
    },
    rest: async (request) => {
      calls.push(`rest ${request.method} ${request.path}`);
      if (request.method === "GET") return new Array(state.rows).fill({});
      if (request.method === "DELETE") state.rows = 0;
      return [];
    },
  };
  return { runner, calls, state };
};

const rowsFixture = (apply: string) =>
  validateFixtures(
    [
      {
        id: "rows",
        why: "a Concept row exists",
        phase: "outside",
        check: { rest: { path: "/rest/v1/Concept?select=id", expect: "rows" } },
        apply: { sql: apply },
      },
    ],
    "prepare",
  );

test("outside fixtures keep what's in place and apply only what's missing", async () => {
  const { runner, calls } = fakeRunner();
  const fixtures = rowsFixture("insert into Concept ...");
  const first = await runOutsideFixtures({ fixtures, runner, context, checkOnly: false });
  assert.deepEqual(first.map((run) => run.status), ["applied"]);
  const second = await runOutsideFixtures({ fixtures, runner, context, checkOnly: false });
  assert.deepEqual(second.map((run) => run.status), ["kept"]);
  assert.equal(calls.filter((call) => call.startsWith("sql")).length, 1);
});

test("check-only changes nothing, and a fixture that doesn't take fails", async () => {
  const { runner, calls } = fakeRunner();
  const looked = await runOutsideFixtures({
    fixtures: rowsFixture("insert into Concept ..."),
    runner,
    context,
    checkOnly: true,
  });
  assert.deepEqual(looked.map((run) => run.status), ["missing"]);
  assert.equal(calls.filter((call) => call.startsWith("sql")).length, 0);

  const broken = await runOutsideFixtures({
    fixtures: rowsFixture("select 1 -- noop"),
    runner,
    context,
    checkOnly: false,
  });
  assert.equal(broken[0].status, "failed");
  assert.match(String(broken[0].detail), /check still fails/);
});

test("in-session fixtures become steps that check, apply and check again", async () => {
  const fixtures = validateFixtures(
    [
      {
        id: "page",
        why: "the fixture page exists",
        phase: "in-session",
        check: { js: "Boolean(window.found)" },
        apply: { js: "window.found = true" },
      },
      {
        id: "setting",
        why: "stored relations are on",
        phase: "in-session",
        check: { js: "true" },
        apply: { steps: [{ do: { click: "#toggle" }, why: "turn it on" }] },
      },
      {
        id: "broken",
        why: "this never takes",
        phase: "in-session",
        check: { js: "false" },
        apply: { js: "0" },
      },
    ],
    "prepare",
  );
  const steps = inSessionSteps(fixtures);
  assert.deepEqual(
    steps.map((step) => step.id),
    ["fixture-page", "fixture-setting-1", "fixture-setting-check", "fixture-broken"],
  );
  assert.ok(steps.every((step) => step.source === "kit"));

  const scope = globalThis as unknown as { window: { found: boolean } };
  scope.window = { found: false };
  const pageJs = (steps[0].do as { js: string }).js;
  assert.equal(await eval(pageJs), "applied");
  assert.equal(await eval(pageJs), "kept");
  await assert.rejects(
    eval((steps[3].do as { js: string }).js) as Promise<unknown>,
    /Fixture broken did not take: this never takes/,
  );
});

test("smoke cases become setup steps with labelled checks", async () => {
  const baseline = validateBaseline({
    name: "dg-baseline",
    version: 1,
    smoke: [
      {
        id: "loaded",
        title: "The extension loaded",
        expect: { js: "(() => { throw new Error('no roamjs'); })()" },
      },
    ],
  });
  const steps = smokeSteps(baseline.smoke);
  assert.deepEqual(steps.map((step) => step.id), ["smoke-loaded-check"]);
  await assert.rejects(
    eval((steps[0].do as { js: string }).js) as Promise<unknown>,
    /Smoke check failed: The extension loaded: no roamjs/,
  );
});

