import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";
import { validateBaseline, validateKit } from "../kit";
import {
  buildTakeStoryboard,
  parseRecordDemoOutput,
  storyboardFromFileSync,
  takeModuleSource,
  takeReadiness,
  takeResults,
} from "../take";

test("a take refuses what it can't run unattended and lists eye-only checks", () => {
  const kit = validateKit({
    name: "k",
    cases: [
      { id: "a", title: "A", intent: "work it out live" },
      {
        id: "b",
        title: "B",
        steps: [{ do: { js: "seed()" }, why: "seed", source: "model" }],
      },
      {
        id: "c",
        title: "C",
        steps: [{ do: { click: "#c" }, why: "c" }],
        expect: { text: "looks right" },
      },
      {
        id: "d",
        title: "D",
        steps: [{ do: { js: "seed()" }, why: "seed", source: "model", approved: true }],
      },
      { id: "e", title: "E", expect: { js: "true" } },
    ],
  });
  const readiness = takeReadiness(kit);
  assert.equal(readiness.blockers.length, 2);
  assert.match(readiness.blockers[0], /a "A" has no steps yet/);
  assert.match(readiness.blockers[1], /b step s1 is js from the brain/);
  assert.deepEqual(readiness.unverified, ['c "C": looks right']);
});

test("cases become scenes, and fixtures and smoke checks become trimmed setup", () => {
  const kit = validateKit({
    name: "eng-2348",
    prepare: [
      {
        id: "page",
        why: "the fixture page exists",
        phase: "in-session",
        check: { js: "true" },
        apply: { js: "make('{{ns}}')" },
      },
    ],
    cases: [
      {
        id: "share",
        title: "Share warns",
        caption: "Share warns before anything leaves the graph.",
        toast: "After: eng-2348 build",
        steps: [{ do: { command_palette: "DG: Share" }, why: "open Share" }],
        expect: { js: "check('{{env.K}}')" },
      },
    ],
  });
  const baseline = validateBaseline({
    name: "dg-baseline",
    version: 1,
    smoke: [{ id: "loaded", title: "Extension loaded", expect: { js: "true" } }],
  });
  const storyboard = buildTakeStoryboard({
    kit,
    baseline,
    sessionDir: "/s",
    distDir: "/d",
    context: { env: { K: "secret" }, kit: kit.name, run: "r" },
  });
  assert.equal(storyboard.output, "/s/eng-2348.webm");
  assert.equal(storyboard.dist, "/d");
  assert.equal(storyboard.scenes.length, 1);
  const [scene] = storyboard.scenes;
  assert.equal(scene.name, "share: Share warns");
  assert.equal(scene.caption, "Share warns before anything leaves the graph.");
  assert.equal(scene.toast, "After: eng-2348 build");
  assert.deepEqual(scene.do?.[0], { command_palette: "DG: Share" });
  const check = scene.do?.[1] as { js: string };
  assert.match(check.js, /check\('secret'\)/);
  assert.match(check.js, /Case share failed/);
  const setup = (storyboard.setup ?? []) as Array<{ js: string }>;
  assert.equal(setup.length, 2);
  assert.match(setup[0].js, /make\('pk-eng-2348'\)/);
  assert.match(setup[1].js, /Smoke check failed: Extension loaded/);
});

test("the generated module builds from the kit file and never holds env values", () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "proof-take-"));
  const kitFile = path.join(dir, "kit.json");
  fs.writeFileSync(
    kitFile,
    JSON.stringify({
      name: "k",
      cases: [{ title: "A", steps: [{ do: { js: "'{{env.PROOF_TEST_KEY}}'" }, why: "x" }] }],
    }),
  );
  const options = { kitFile, sessionDir: dir, distDir: null, run: "r" };
  try {
    const source = takeModuleSource(options);
    assert.match(source, /storyboardFromFileSync/);
    assert.doesNotMatch(source, /hush/);
    assert.throws(() => storyboardFromFileSync(options), /PROOF_TEST_KEY/);
    process.env.PROOF_TEST_KEY = "hush";
    const storyboard = storyboardFromFileSync(options);
    assert.deepEqual(storyboard.scenes[0].do, [{ js: "'hush'" }]);
  } finally {
    delete process.env.PROOF_TEST_KEY;
    fs.rmSync(dir, { recursive: true, force: true });
  }
});

test("recordDemo's output says which case failed, or that setup or the video did", () => {
  const kit = validateKit({
    name: "k",
    cases: [
      { id: "a", title: "A", steps: [{ do: { click: "#a" }, why: "a" }] },
      {
        id: "b",
        title: "B",
        steps: [{ do: { click: "#b" }, why: "b" }],
        expect: { js: "x" },
      },
      {
        id: "c",
        title: "C",
        steps: [{ do: { click: "#c" }, why: "c" }],
        expect: { text: "looks right" },
      },
    ],
  });
  const scenes = (count: number): string =>
    ["a: A", "b: B", "c: C"]
      .slice(0, count)
      .map((name, index) => `[recordDemo] Scene ${index + 1}/3: ${name}`)
      .join("\n");

  const ok = takeResults(
    kit,
    parseRecordDemoOutput(`${scenes(3)}\n[recordDemo] Demo video: /s/k.mp4\n`, "", 0),
  );
  assert.deepEqual(ok.cases.map((item) => item.result), ["pass", "pass", "shown"]);

  const caseFailed = parseRecordDemoOutput(
    `${scenes(2)}\n[recordDemo] Failed-run video: /s/k-failed.webm\n`,
    "Error: Case b failed: Expected 2 rows, saw 1\n    at evaluate",
    1,
  );
  assert.equal(caseFailed.failedVideo, "/s/k-failed.webm");
  const failed = takeResults(kit, caseFailed);
  assert.deepEqual(failed.cases.map((item) => item.result), ["pass", "fail", "not run"]);
  assert.match(String(failed.cases[1].note), /Case b failed: Expected 2 rows/);

  const setup = takeResults(
    kit,
    parseRecordDemoOutput("", "Error: Fixture page did not take: fixture page\n", 1),
  );
  assert.match(String(setup.setupFailure), /Fixture page did not take/);
  assert.deepEqual(setup.cases.map((item) => item.result), ["not run", "not run", "not run"]);

  const recording = takeResults(
    kit,
    parseRecordDemoOutput(scenes(3), "Error: ffmpeg exited with 1:\nbad filter", 1),
  );
  assert.match(String(recording.recordingFailure), /ffmpeg exited/);
  assert.deepEqual(recording.cases.map((item) => item.result), ["pass", "pass", "shown"]);
});

