import assert from "node:assert/strict";
import test from "node:test";
import { envRefs, fill, fillDeep } from "../template";

const context = {
  env: { SUPABASE_SERVICE_ROLE_KEY: "k123", A_KEY: "a", B_KEY: "b" },
  kit: "eng-2348",
  run: "r1",
};

test("tokens fill from the env, the kit and the run; a missing env value names itself", () => {
  assert.equal(
    fill(
      "key={{env.SUPABASE_SERVICE_ROLE_KEY}} kit={{kit}} run={{run}} ns={{ns}}",
      context,
    ),
    "key=k123 kit=eng-2348 run=r1 ns=pk-eng-2348",
  );
  assert.throws(
    () => fill("{{env.MISSING_KEY}}", context),
    /\{\{env\.MISSING_KEY\}\} is not set/,
  );
  assert.equal(
    fill("`${x}` and {{other}} stay as they are", context),
    "`${x}` and {{other}} stay as they are",
  );
});

test("fillDeep leaves the original alone, and envRefs finds every env name", () => {
  const kit = {
    cases: [{ steps: [{ do: { js: "fetch('{{env.A_KEY}}')" } }] }],
    prepare: [{ apply: { rest: { path: "/rest/v1/x?k={{env.B_KEY}}" } } }],
  };
  const filled = fillDeep(kit, context);
  assert.equal(filled.cases[0].steps[0].do.js, "fetch('a')");
  assert.equal(filled.prepare[0].apply.rest.path, "/rest/v1/x?k=b");
  assert.equal(kit.cases[0].steps[0].do.js, "fetch('{{env.A_KEY}}')");
  assert.deepEqual(envRefs(kit), ["A_KEY", "B_KEY"]);
});

import assert from "node:assert/strict";
import test from "node:test";
import { validateKit } from "../kit";
import { checkNeeds, collectNeeds, type Probes } from "../needs";

const fakeProbes = (overrides: Partial<Probes> = {}): Probes => ({
  http: async () => 200,
  shell: async () => ({ code: 0, output: "" }),
  readFile: async () =>
    'x buildCommit:"abc1234def5678" 127.0.0.1:54321 127.0.0.1:3210',
  prHead: async () => "abc1234def5678",
  ...overrides,
});

test("needs come from the kit and from what its fixtures and strings imply", () => {
  const kit = validateKit({
    name: "k",
    needs: ["embed-stub"],
    prepare: [
      {
        id: "rows",
        why: "seed Concept rows",
        phase: "outside",
        apply: { rest: { method: "POST", path: "/rest/v1/Concept", body: {} } },
      },
    ],
    cases: [
      {
        title: "A",
        steps: [{ do: { js: "'{{env.SUPABASE_PUBLISHABLE_KEY}}'" }, why: "x" }],
      },
    ],
  });
  const ids = collectNeeds(kit, null)
    .map((need) => (typeof need === "string" ? need : need.id))
    .sort();
  assert.deepEqual(ids, [
    "embed-stub",
    "env:SUPABASE_PUBLISHABLE_KEY",
    "env:SUPABASE_SERVICE_ROLE_KEY",
    "supabase",
  ]);
});

test("a need that isn't met comes with the command that fixes it", async () => {
  const kit = validateKit({
    name: "k",
    needs: ["supabase", "env:SUPABASE_SERVICE_ROLE_KEY"],
    cases: [{ title: "A", intent: "x" }],
  });
  const results = await checkNeeds({
    kit,
    baseline: null,
    distDir: null,
    env: {},
    probes: fakeProbes({ http: async () => null }),
  });
  const supabase = results.find((result) => result.id === "supabase");
  assert.equal(supabase?.ok, false);
  assert.match(String(supabase?.fix), /npx supabase start/);
  const key = results.find((result) => result.id === "env:SUPABASE_SERVICE_ROLE_KEY");
  assert.equal(key?.ok, false);
  assert.match(String(key?.fix), /\.env\.local/);
});

test("the dist needs the right env baked in and must be the PR's head", async () => {
  const kit = validateKit({
    name: "k",
    needs: ["supabase", "embed-stub"],
    target: { pr: 1506 },
    cases: [{ title: "A", intent: "x" }],
  });
  const probes = fakeProbes({
    readFile: async () => 'buildCommit:"1111111aaaa" 127.0.0.1:54321',
    prHead: async () => "2222222bbbb",
  });
  const stale = await checkNeeds({ kit, baseline: null, distDir: "/dist", env: {}, probes });
  assert.equal(stale.find((result) => result.id === "dist:127.0.0.1:54321")?.ok, true);
  assert.equal(stale.find((result) => result.id === "dist:127.0.0.1:3210")?.ok, false);
  const head = stale.find((result) => result.id === "dist:pr-head");
  assert.equal(head?.ok, false);
  assert.match(String(head?.detail), /1111111.*2222222/);
  const allowed = await checkNeeds({
    kit,
    baseline: null,
    distDir: "/dist",
    env: {},
    probes,
    allowStaleBuild: true,
  });
  assert.equal(allowed.find((result) => result.id === "dist:pr-head")?.ok, true);
});

import assert from "node:assert/strict";
import test from "node:test";
import {
  inSessionSteps,
  runOutsideFixtures,
  smokeSteps,
  type OutsideRunner,
} from "../fixtures";
import { validateBaseline, validateFixtures } from "../kit";

const context = { env: {}, kit: "k", run: "r" };

const fakeRunner = () => {
  const calls: string[] = [];
  const state = { rows: 0 };
  const runner: OutsideRunner = {
    shell: async (command) => {
      calls.push(`shell ${command}`);
      return { code: command.includes("fail") ? 1 : 0, output: "" };
    },
    sql: async (statement) => {
      calls.push(`sql ${statement}`);
      if (!statement.includes("noop")) state.rows += 1;
      return { code: 0, output: "INSERT 0 1" };
    },
    rest: async (request) => {
      calls.push(`rest ${request.method} ${request.path}`);
      if (request.method === "GET") return new Array(state.rows).fill({});
      if (request.method === "DELETE") state.rows = 0;
      return [];
    },
  };
  return { runner, calls, state };
};

const rowsFixture = (apply: string) =>
  validateFixtures(
    [
      {
        id: "rows",
        why: "a Concept row exists",
        phase: "outside",
        check: { rest: { path: "/rest/v1/Concept?select=id", expect: "rows" } },
        apply: { sql: apply },
      },
    ],
    "prepare",
  );

test("outside fixtures keep what's in place and apply only what's missing", async () => {
  const { runner, calls } = fakeRunner();
  const fixtures = rowsFixture("insert into Concept ...");
  const first = await runOutsideFixtures({ fixtures, runner, context, checkOnly: false });
  assert.deepEqual(first.map((run) => run.status), ["applied"]);
  const second = await runOutsideFixtures({ fixtures, runner, context, checkOnly: false });
  assert.deepEqual(second.map((run) => run.status), ["kept"]);
  assert.equal(calls.filter((call) => call.startsWith("sql")).length, 1);
});

test("check-only changes nothing, and a fixture that doesn't take fails", async () => {
  const { runner, calls } = fakeRunner();
  const looked = await runOutsideFixtures({
    fixtures: rowsFixture("insert into Concept ..."),
    runner,
    context,
    checkOnly: true,
  });
  assert.deepEqual(looked.map((run) => run.status), ["missing"]);
  assert.equal(calls.filter((call) => call.startsWith("sql")).length, 0);

  const broken = await runOutsideFixtures({
    fixtures: rowsFixture("select 1 -- noop"),
    runner,
    context,
    checkOnly: false,
  });
  assert.equal(broken[0].status, "failed");
  assert.match(String(broken[0].detail), /check still fails/);
});

test("in-session fixtures become steps that check, apply and check again", async () => {
  const fixtures = validateFixtures(
    [
      {
        id: "page",
        why: "the fixture page exists",
        phase: "in-session",
        check: { js: "Boolean(window.found)" },
        apply: { js: "window.found = true" },
      },
      {
        id: "setting",
        why: "stored relations are on",
        phase: "in-session",
        check: { js: "true" },
        apply: { steps: [{ do: { click: "#toggle" }, why: "turn it on" }] },
      },
      {
        id: "broken",
        why: "this never takes",
        phase: "in-session",
        check: { js: "false" },
        apply: { js: "0" },
      },
    ],
    "prepare",
  );
  const steps = inSessionSteps(fixtures);
  assert.deepEqual(
    steps.map((step) => step.id),
    ["fixture-page", "fixture-setting-1", "fixture-setting-check", "fixture-broken"],
  );
  assert.ok(steps.every((step) => step.source === "kit"));

  const scope = globalThis as unknown as { window: { found: boolean } };
  scope.window = { found: false };
  const pageJs = (steps[0].do as { js: string }).js;
  assert.equal(await eval(pageJs), "applied");
  assert.equal(await eval(pageJs), "kept");
  await assert.rejects(
    eval((steps[3].do as { js: string }).js) as Promise<unknown>,
    /Fixture broken did not take: this never takes/,
  );
});

test("smoke cases become setup steps with labelled checks", async () => {
  const baseline = validateBaseline({
    name: "dg-baseline",
    version: 1,
    smoke: [
      {
        id: "loaded",
        title: "The extension loaded",
        expect: { js: "(() => { throw new Error('no roamjs'); })()" },
      },
    ],
  });
  const steps = smokeSteps(baseline.smoke);
  assert.deepEqual(steps.map((step) => step.id), ["smoke-loaded-check"]);
  await assert.rejects(
    eval((steps[0].do as { js: string }).js) as Promise<unknown>,
    /Smoke check failed: The extension loaded: no roamjs/,
  );
});

import assert from "node:assert/strict";
